#!/bin/bash\n# BPF trace collection for cpu-bound-burstable\n# Generated: 2026-10-26 15:51:19\n\n# === BPF Trace Collection on Kubernetes Node ===\n# Pod: cpu-bound-burstable\n# Node: k8labs-md-custom-4vcpu-qq498-zlz6p-6n655\n# UID: 2dec945a-227a-48e3-850a-fcd3a498cbca\n# QoS: burstable\n\n# 1. Install bpftrace if needed\nsudo dnf install -y bpftrace\n\n# 2. Find container PID\nCGROUP_PATH="/sys/fs/cgroup/kubepods.slice/kubepods-burstable.slice/kubepods-burstable-pod2dec945a-227a-48e3-850a-fcd3a498cbca.slice"\nCONTAINER_PID=$(cat ${CGROUP_PATH}/cgroup.procs | head -1)\necho "Container PID: $CONTAINER_PID"\nps -p $CONTAINER_PID -o pid,comm,cmd\n\n# 3. Run throttle trace\nsudo timeout 30s bpftrace -e '\ntracepoint:sched:sched_cfs_quota_throttled {\n  printf("%s[%d] throttled for %d us\n",\n    args->comm, args->pid, args->throttled_usec);\n  @throttle_events++;\n  @total_throttled_us += args->throttled_usec;\n}\nEND {\n  printf("\nTotal throttle events: %d\n", @throttle_events);\n  printf("Total throttled time: %d us\n", @total_throttled_us);\n}\n' > /tmp/bpf-trace-cpu-bound-burstable.txt\n\n# 4. Monitor cgroup stats (run in separate terminal)\nwhile true; do\n  echo "$(date +%s) $(cat ${CGROUP_PATH}/cpu.stat)"\n  sleep 1\ndone > /tmp/cgroup-stats-cpu-bound-burstable.txt